const testScales={'IELTS':{min:0,max:9,step:.5,label:'IELTS · 0–9'},'TOEFL':{min:1,max:6,step:.5,label:'TOEFL iBT · 1–6'},'TOEFL-120':{min:0,max:120,step:1,label:'TOEFL iBT · 0–120'},'DET':{min:10,max:160,step:5,label:'DET · 10–160'}};
function renderClientTests(c){return `<div class="section-top" style="margin-top:28px"><h2>Языковые тесты</h2><button data-test="add" data-client="${c.id}">Добавить результат</button></div>${(c.tests||[]).length?`<div class="tablewrap"><table><thead><tr><th>Тест / шкала</th><th>Результат</th><th>Дата сдачи</th><th></th></tr></thead><tbody>${c.tests.map(t=>`<tr><td>${esc(testScales[t.type]?.label||t.type)}</td><td><strong>${esc(t.score)}</strong></td><td>${esc(t.date?fullDate(t.date):'Не указана')}</td><td><button data-test="edit" data-client="${c.id}" data-id="${t.id}">Изменить</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="subtle">Результатов пока нет. Можно добавить несколько тестов и пересдачи.</p>'}`}
function testForm(c,t){showModal(t?'Изменить результат':'Добавить результат',`<form id="test-form" data-client="${c.id}" data-id="${t?.id||''}"><label>Тест и шкала<select name="type" id="test-type">${Object.entries(testScales).map(([key,v])=>`<option value="${key}" ${t?.type===key?'selected':''}>${v.label}</option>`).join('')}</select></label><label>Общий результат<input id="test-score" name="score" type="number" required value="${t?.score??''}"></label><p class="subtle" id="test-hint"></p><label>Дата сдачи<input type="date" name="date" max="${iso(new Date())}" value="${esc(t?.date||'')}"></label><p class="subtle">Указывайте балл из сертификата. Для TOEFL выбирайте шкалу, указанную в результате; пересчёт не выполняется.</p>${footer('Сохранить результат')}</form>`);updateTestScale()}
function updateTestScale(){const scale=testScales[$('#test-type').value],input=$('#test-score');input.min=scale.min;input.max=scale.max;input.step=scale.step;$('#test-hint').textContent=`От ${scale.min} до ${scale.max}, шаг ${scale.step}.`}
document.addEventListener('change',e=>{if(e.target.id==='test-type')updateTestScale()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-test]');if(!b)return;const c=clientById(b.dataset.client);if(c)testForm(c,c.tests?.find(t=>t.id===b.dataset.id))});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='test-form')return;e.preventDefault();const data=Object.fromEntries(new FormData(form)),scale=testScales[data.type],score=Number(data.score);if(!scale||data.score===''||!Number.isFinite(score)||score<scale.min||score>scale.max||!Number.isInteger((score-scale.min)/scale.step)){$('#form-error').textContent='Проверьте балл и выбранную шкалу.';return}if(data.date&&(!reportDateValid(data.date)||data.date>iso(new Date()))){$('#form-error').textContent='Укажите корректную дату не позже сегодня.';return}const c=clientById(form.dataset.client),before=structuredClone(c.tests||[]);c.tests=c.tests||[];const value={id:form.dataset.id||crypto.randomUUID(),type:data.type,score,date:data.date};const index=c.tests.findIndex(t=>t.id===value.id);if(index<0)c.tests.push(value);else c.tests[index]=value;if(await save()){$('#modal').close();render();toast('Результат сохранён')}else c.tests=before});
